<script>
 import { onMount } from 'svelte';
 onMount(() => {
   let stopped = false;
   let dispose;
   import('./motion.js').then(({ mountMotion }) => {
     if (!stopped) dispose = mountMotion(document.getElementById('app'));
   }).catch((error) => console.warn('Animace se nepodařilo načíst.', error));
   return () => { stopped = true; dispose?.(); };
 });
 import { ArrowUpRight, ArrowRight, MessageSquare, CalendarCheck, House, Brush, Layers, Wrench, Phone, Menu, X, Check, MapPin, PaintRoller, ShieldCheck, MoveHorizontal, ChevronLeft, ChevronRight } from 'lucide-svelte';
 import { services, projects, faqs } from './data.js';
 let { path = '/' } = $props();
 const route = $derived(path.split('/').pop()?.replace('.html','') || 'index');
 const home = $derived(route === 'index');
 const service = $derived(services.find(s => s.slug === route));
 const isGallery = $derived(route === 'realizace');
 const isContact = $derived(route === 'kontakt');
 const isLocations = $derived(route === 'lokality-jihlava-vysocina');
 let menuOpen = $state(false);
 let quoteDialog;
 let photoDialog;
 let filter = $state('Vše');
 let photoIndex = $state(0);
 let comparison = $state(50);
 let smsText = $state('');
 let copied = $state(false);
 const filteredProjects = $derived(filter === 'Vše' ? projects : projects.filter(p=>p.category===filter));
 function openQuote(){ menuOpen=false; smsText=''; quoteDialog.showModal(); }
 function openPhoto(p){photoIndex=filteredProjects.indexOf(p); photoDialog.showModal();}
 function stepPhoto(n){photoIndex=(photoIndex+n+filteredProjects.length)%filteredProjects.length;}
 function prepareSms(event){event.preventDefault();const d=new FormData(event.currentTarget);smsText=`Dobrý den, mám zájem o nezávaznou nabídku.\nJméno: ${d.get('name')}\nLokalita: ${d.get('location')}\nTyp práce: ${d.get('service')}\nTermín: ${d.get('term')||'Dle domluvy'}\nPopis: ${d.get('message')||'Upřesním při domluvě.'}`;copied=false;}
 async function copyText(){try{await navigator.clipboard.writeText(smsText);copied=true;}catch{copied=false;}}
</script>

<svelte:head>
 <title>{home ? 'Špejtek — Malířství & natěračství Jihlava' : `${service?.title || (isGallery ? 'Realizace' : isContact ? 'Kontakt' : isLocations ? 'Jihlava a Vysočina' : 'Stránka nenalezena')} | Malířství Špejtek`}</title>
 <meta name="description" content={service?.description || 'Poctivé malířství a natěračství v Jihlavě a na Vysočině. Výmalby, dekorativní stěrky, fasády a nátěry. Nezávazná nabídka zdarma.'}/>
 <link rel="canonical" href={`https://malirstvi-spejtek.net/${home ? '' : route+'.html'}`}/>
</svelte:head>
<svelte:window onkeydown={(e)=>{if(e.key==='Escape')menuOpen=false;if(photoDialog?.open){if(e.key==='ArrowRight')stepPhoto(1);if(e.key==='ArrowLeft')stepPhoto(-1);}}}/>

{#snippet brand(light=false)}
 <a class:light class="brand" href="/" aria-label="Špejtek — úvodní stránka"><img class="brand-symbol" src="/assets/img/spejtek-roller.svg" alt=""/><span class="brand-name">ŠPEJTEK<span>Malířství & natěračství</span></span></a>
{/snippet}
{#snippet quoteButton(text='Nezávazná poptávka',extra='')}
 <button class={`btn ${extra}`} onclick={openQuote}>{text}<ArrowUpRight size={19}/></button>
{/snippet}
<a class="skip-link" href="#obsah">Přejít na obsah</a>
<header class="header">
 <div class="shell header-inner">{@render brand()}<nav class="desktop-nav" aria-label="Hlavní navigace"><a class:active={home} href="/">Úvod</a><a class:active={!!service} href="/#sluzby">Služby</a><a class:active={isGallery} href="/realizace.html">Realizace</a><a href="/#pristup">Náš přístup</a><a class:active={isContact} href="/kontakt.html">Kontakt</a></nav><div class="header-actions"><a class="header-phone" href="tel:+420602581542"><Phone size={16}/>602 581 542</a>{@render quoteButton('Poptat práci','small')}<button class="menu-toggle" aria-label={menuOpen?'Zavřít menu':'Otevřít menu'} aria-expanded={menuOpen} aria-controls="mobile-nav" onclick={()=>menuOpen=!menuOpen}>{#if menuOpen}<X/>{:else}<Menu/>{/if}</button></div></div>
 {#if menuOpen}<nav id="mobile-nav" class="mobile-nav" aria-label="Mobilní navigace">{#each [['/','Úvod'],['/#sluzby','Služby'],['/realizace.html','Realizace'],['/#pristup','Náš přístup'],['/kontakt.html','Kontakt']] as [url,label]}<a href={url} onclick={()=>menuOpen=false}>{label}<ArrowUpRight size={20}/></a>{/each}{@render quoteButton()}</nav>{/if}
</header>
<main id="obsah">
 {#if home}
 <section class="hero">
 <div class="shell hero-heading"><div class="eyebrow hero-badge"><MapPin size={15}/> Malířství Jihlava & Vysočina</div><h1>Čerstvá barva.<br/><em>Úplně nový pocit.</em></h1><p>Malování, stěrky a nátěry, se kterými váš prostor ožije.<br class="desktop-break"/> Poctivě od první domluvy až po poslední detail.</p><div class="hero-actions">{@render quoteButton('Chci nezávaznou nabídku')}<a class="btn secondary" href="/realizace.html">Prohlédnout realizace <ArrowRight size={18}/></a></div></div>
 <div class="shell hero-showcase"><a class="showcase-tile showcase-main" href="/malirske-prace-jihlava.html"><img src="/assets/img/hero-malir-na-leseni.webp" alt="Malířství Špejtek při výmalbě komerčních prostor" fetchpriority="high"/><div><span>Od bytů po velké prostory</span><strong>Malování interiérů <ArrowUpRight/></strong></div></a><a class="showcase-tile" href="/dekorativni-sterky-jihlava.html"><img src="/assets/img/betonova-sterka-seda.webp" alt="Šedá betonová stěrka"/><div><span>Povrchy s charakterem</span><strong>Dekorativní stěrky <ArrowUpRight/></strong></div></a><div class="showcase-blue"><span class="showcase-icon"><PaintRoller size={30}/></span><h2>Vaše představa.<br/>Naše řemeslo.</h2><a href="/kontakt.html">Pojďme se domluvit <ArrowUpRight size={23}/></a></div></div>
 <div class="shell trust-row"><span><ShieldCheck size={20}/> Pečlivá příprava i úklid</span><span><MessageSquare size={20}/> Přímá domluva s řemeslníkem</span><span><Check size={20}/> Nezávazná nabídka zdarma</span></div>
 </section>
 <section class="section shell" id="sluzby"><div class="section-heading centered"><div class="eyebrow">Co pro vás uděláme</div><h2>Od jedné stěny<br/>po celý dům.</h2><p>Vyberte, s čím vám pomůžeme. O zbytek se společně postaráme.</p></div><div class="services-grid">{#each services as s,i}<a class="service-card" href={`/${s.slug}.html`}><span class="service-icon">{#if i===0}<PaintRoller/>{:else if i===1}<House/>{:else if i===2}<Layers/>{:else if i===3}<ShieldCheck/>{:else if i===4}<Brush/>{:else}<Wrench/>{/if}</span><div><h3>{s.title}</h3><p>{s.description}</p></div><ArrowUpRight class="service-arrow" size={22}/></a>{/each}</div></section>
 <section class="work-section" id="realizace"><div class="shell"><div class="section-heading"><div><div class="eyebrow">Naše realizace</div><h2>Tady za nás<br/>mluví výsledek.</h2></div><a class="btn secondary" href="/realizace.html">Všechny realizace <ArrowUpRight size={20}/></a></div><div class="project-grid home-projects">{#each projects.slice(0,3) as project}{@render projectCard(project)}{/each}</div></div></section>
 <section class="section shell craft-section" id="pristup"><div class="craft-grid"><div class="craft-copy"><div class="eyebrow">Řemeslo s osobním přístupem</div><h2>Dobře vymalováno.<br/><em>Bez zbytečných starostí.</em></h2><p>Záleží nám na výsledku i na tom, jak se k němu dostaneme. Proto si všechno domluvíme předem a k vašemu prostoru přistupujeme jako k vlastnímu.</p><div class="craft-points">{#each [['Domluva, která platí','Rozsah, postup i termín si ujasníme předem.'],['Váš domov v dobrých rukou','Zakryjeme vybavení a připravíme každý povrch.'],['Záleží na každém detailu','Zkontrolujeme hrany, přechody a sjednocení odstínu.']] as [title,desc]}<div><span><Check size={18}/></span><div><h3>{title}</h3><p>{desc}</p></div></div>{/each}</div>{@render quoteButton('Domluvit svou zakázku')}</div><div class="craft-photo"><img src="/assets/img/dekorativni-sterka-detail.webp" alt="Pečlivé ruční nanášení dekorativní stěrky" loading="lazy"/><div class="photo-label"><ShieldCheck size={26}/><span>Poctivá práce.<strong>Od podkladu až po povrch.</strong></span></div></div></div></section>
 <section class="comparison-section shell"><div class="comparison" style={`--position:${comparison}%`}><img src="/assets/img/interier-pred.webp" alt="Interiér před malováním" loading="lazy"/><img class="after-photo" src="/assets/img/interier-po.webp" alt="Interiér po dokončené výmalbě" loading="lazy"/><span class="before-label">Před</span><span class="after-label">Po</span><div class="compare-divider"><span><MoveHorizontal size={22}/></span></div><input type="range" min="0" max="100" bind:value={comparison} aria-label="Porovnání interiéru před a po malování"/></div><div class="comparison-copy"><div class="eyebrow">Rozdíl je vidět</div><h2>Váš domov.<br/>V novém světle.</h2><p>Opravené stěny, svěží barva a čisté detaily. Podívejte se, co dokáže poctivá výmalba.</p><span class="compare-hint"><MoveHorizontal size={20}/> Posuňte a porovnejte proměnu</span></div></section>
 {@render processSection()}
 <section class="section shell faq-section"><div><div class="eyebrow">Časté otázky</div><h2>Co vás zajímá?</h2><p>Nenašli jste odpověď?<br/>Zavolejte, rádi to s vámi probereme.</p><a class="text-link" href="tel:+420602581542"><Phone size={19}/>602 581 542</a></div><div>{#each faqs as [question,answer]}<details><summary>{question}<span>+</span></summary><p>{answer}</p></details>{/each}</div></section>
 {:else if service}
 <section class="shell detail-hero"><div><a class="breadcrumb" href="/#sluzby">Služby / {service.title}</a><div class="eyebrow">MALÍŘSTVÍ ŠPEJTEK · JIHLAVA A VYSOČINA</div><h1>{service.title}<em>{service.short}</em></h1><p class="lead">{service.description}</p>{@render quoteButton('Poptat tuto službu')}</div><img src={`/assets/img/${service.image}`} alt={service.title} fetchpriority="high"/></section><section class="shell section detail-inclusions"><div><div class="eyebrow">OD PŘÍPRAVY PO DOKONČENÍ</div><h2>Co pro vás<br/><em>zajistíme.</em></h2></div><div>{#each service.details as detail}<div class="inclusion"><Check size={21}/><h3>{detail}</h3></div>{/each}<p>Konkrétní rozsah práce, materiál a cenu domluvíme podle stavu povrchu. Pro první nabídku stačí fotografie, lokalita a přibližná velikost plochy.</p></div></section>{@render processSection()}<section class="shell section"><div class="section-heading"><h2>Všechno pro<br/><em>váš prostor.</em></h2><a href="/#sluzby" class="text-link">Přehled služeb <ArrowRight size={18}/></a></div><div class="related-services">{#each services.filter(s=>s!==service).slice(0,3) as s}<a href={`/${s.slug}.html`}>{s.title}<ArrowUpRight size={22}/></a>{/each}</div></section>
 {:else if isGallery}
 <section class="shell page-intro"><div class="eyebrow">Naše práce</div><h1>Řemeslo, které<br/><em>mluví za sebe.</em></h1><p class="lead">Povrchy, prostory a detaily z našich zakázek.<br/>Od první přípravy až po hotový výsledek.</p></section><section class="shell gallery-section"><div class="filters" aria-label="Filtrovat realizace">{#each ['Vše','Interiéry','Stěrky','Exteriéry','Nátěry'] as category}<button class:selected={filter===category} aria-pressed={filter===category} onclick={()=>filter=category}>{category}<span>{category==='Vše'?projects.length:projects.filter(p=>p.category===category).length}</span></button>{/each}</div><div class="project-grid">{#each filteredProjects as project,i}{@render projectCard(project)}{/each}</div></section>
 {:else if isContact}
 <section class="shell page-intro"><div class="eyebrow">Jsme tu pro vás</div><h1>Váš prostor.<br/><em>Náš další projekt.</em></h1><p class="lead">Řekněte nám, co chcete proměnit.<br/>Společně najdeme vhodný postup i termín.</p></section><section class="shell contact-grid"><div class="contact-card"><span class="eyebrow">ZAVOLEJTE PŘÍMO ŘEMESLNÍKOVI</span><a class="big-phone" href="tel:+420602581542">602 581 542 <ArrowUpRight/></a><p>Nejjednodušší cesta k první domluvě.<br/>Nebo pošlete popis zakázky ve zprávě.</p><div class="contact-location"><MapPin size={22}/><div><strong>Jihlava a okolí</strong><p>Po dohodě celá Vysočina.</p></div></div><a class="text-link" href="/lokality-jihlava-vysocina.html">Kde pracujeme <ArrowRight size={18}/></a></div><div class="contact-form"><div class="eyebrow">NEZÁVAZNÁ NABÍDKA ZDARMA</div><h2>Máte představu?<br/><em>Napište nám.</em></h2>{@render quoteForm('contact')}</div></section>
 {:else if isLocations}
 <section class="shell page-intro"><div class="eyebrow">Kde pracujeme</div><h1>Doma v Jihlavě.<br/><em>Po celé Vysočině.</em></h1><p class="lead">Pracujeme v Jihlavě a okolních obcích.<br/>Za většími zakázkami přijedeme i do dalších částí kraje.</p></section><section class="shell locations-grid"><div class="location-art"><MapPin size={70} strokeWidth={1}/><h2>Jihlava</h2><span>VYSOČINA · ČESKÁ REPUBLIKA</span><div class="location-rings"></div></div><div><div class="eyebrow">OBLAST PŮSOBNOSTI</div>{#each ['Jihlava a okolní obce','Třešť a Telč','Polná a Velké Meziříčí','Pelhřimov a Humpolec'] as city}<div class="city-row">{city}<ArrowUpRight size={20}/></div>{/each}<p>Vaše obec tu není? Ozvěte se. Dostupnost domluvíme podle místa a rozsahu práce.</p>{@render quoteButton('Domluvit zakázku')}</div></section>
 {:else}
 <section class="shell page-intro"><div class="eyebrow">404 / TADY JE ZATÍM BÍLÁ STĚNA</div><h1>Tahle stránka<br/><em>tu není.</em></h1><p class="lead">Vraťte se na úvod nebo nám zavolejte.</p><a class="btn" href="/">Zpět na úvod <ArrowRight size={18}/></a></section>
 {/if}
 {#if !isContact}<section class="final-cta"><div class="shell"><div class="eyebrow">Pojďme do toho společně</div><div class="cta-row"><h2>Je čas na změnu?<br/><em>Začneme u vás.</em></h2><div>{@render quoteButton('Pojďme to proměnit','light-btn')}<a class="cta-phone" href="tel:+420602581542"><Phone size={17}/> +420 602 581 542</a></div></div><div class="cta-bottom"><span>Nabídka zdarma a bez závazků</span><span><MapPin size={15}/> Jihlava & Vysočina</span></div></div></section>{/if}
</main>
<footer><div class="shell"><div class="footer-top"><div>{@render brand(true)}<p>Poctivé řemeslo.<br/>Pro místa, na kterých vám záleží.</p></div><div><span class="footer-label">CO DĚLÁME</span>{#each services.slice(0,3) as s}<a href={`/${s.slug}.html`}>{s.title}</a>{/each}</div><div><span class="footer-label">A TAKÉ</span>{#each services.slice(3) as s}<a href={`/${s.slug}.html`}>{s.title}</a>{/each}</div><div><span class="footer-label">ZŮSTAŇME V KONTAKTU</span><a href="tel:+420602581542">+420 602 581 542 <ArrowUpRight size={15}/></a><a href="/lokality-jihlava-vysocina.html">Jihlava & Vysočina</a><a href="/kontakt.html">Nezávazná poptávka <ArrowUpRight size={15}/></a></div></div><div class="footer-bottom"><span>© {new Date().getFullYear()} Malířství Špejtek</span><span>Od přípravy podkladu po poslední detail.</span><a href="#obsah">Zpět nahoru <ArrowUpRight size={15}/></a></div></div></footer>

{#snippet projectCard(project)}
 <button class="project-card" onclick={()=>openPhoto(project)} aria-label={`Zvětšit: ${project.caption}`}><div class="project-image"><img src={`/assets/img/${project.image}`} alt={project.caption} loading="lazy"/><span class="project-tag">{project.category}</span><span class="project-open"><ArrowUpRight size={24}/></span></div><div class="project-caption"><div><span>{project.caption}</span><h3>{project.title}</h3></div></div></button>
{/snippet}
{#snippet processSection()}
 <section class="process-section"><div class="shell"><div class="section-heading centered"><div class="eyebrow">Od domluvy k hotovému prostoru</div><h2>S námi to jde jednoduše.</h2></div><div class="process-grid">{#each [[MessageSquare,'Ozvěte se','Pošlete fotografie, lokalitu a přibližný rozsah. Nebo nám rovnou zavolejte.'],[CalendarCheck,'Domluvíme detaily','Upřesníme postup, materiál, cenu a termín. Případně přijedeme na prohlídku.'],[PaintRoller,'Pustíme se do práce','Ochráníme okolí, připravíme povrchy a postaráme se o pečlivý výsledek.']] as [Icon,title,desc]}<div><span class="process-icon"><Icon size={26}/></span><h3>{title}</h3><p>{desc}</p></div>{/each}</div></div></section>
{/snippet}
{#snippet quoteForm(prefix)}
 <p class="form-help">Vyplňte pár údajů. Připravíme text SMS, který si před odesláním můžete zkontrolovat a doplnit o fotografie.</p><form onsubmit={prepareSms}><div class="form-grid"><label for={`${prefix}-name`}>Vaše jméno<input id={`${prefix}-name`} name="name" autocomplete="name" placeholder="Jan Novák" required/></label><label for={`${prefix}-location`}>Lokalita<input id={`${prefix}-location`} name="location" autocomplete="address-level2" placeholder="Např. Jihlava" required/></label><label for={`${prefix}-service`}>S čím pomůžeme<select id={`${prefix}-service`} name="service">{#each services as s}<option selected={s===service}>{s.title}</option>{/each}<option>Jiná práce</option></select></label><label for={`${prefix}-term`}>Přibližný termín<input id={`${prefix}-term`} name="term" placeholder="Dle domluvy"/></label><label class="full" for={`${prefix}-message`}>Vaše představa<textarea id={`${prefix}-message`} name="message" rows="3" placeholder="Počet místností, stav stěn, přibližný rozsah…"></textarea></label></div><button type="submit" class="btn">Připravit poptávku <ArrowRight size={18}/></button><p class="form-footnote">Zprávu odešlete až po potvrzení ve své SMS aplikaci.</p></form>{#if smsText}<div class="sms-preview" aria-live="polite"><h3>Vaše zpráva je připravená</h3><p>Otevřete SMS a potvrďte odeslání v telefonu. Na počítači můžete text zkopírovat.</p><pre>{smsText}</pre><div class="sms-actions"><a class="btn" href={`sms:+420602581542?&body=${encodeURIComponent(smsText)}`}>Otevřít SMS <ArrowUpRight size={17}/></a><button class="text-link" onclick={copyText}>{copied?'Zkopírováno ✓':'Kopírovat text'}</button></div></div>{/if}
{/snippet}
<dialog bind:this={quoteDialog} class="quote-dialog" aria-labelledby="quote-title"><button class="dialog-close" aria-label="Zavřít poptávku" onclick={()=>quoteDialog.close()}><X/></button><div class="eyebrow">NEZÁVAZNÁ NABÍDKA</div><h2 id="quote-title">Začněme vaší<br/><em>představou.</em></h2>{@render quoteForm('modal')}</dialog>
<dialog bind:this={photoDialog} class="photo-dialog" aria-label="Detail realizace"><button class="dialog-close" aria-label="Zavřít fotografii" onclick={()=>photoDialog.close()}><X/></button>{#if filteredProjects[photoIndex]}<img src={`/assets/img/${filteredProjects[photoIndex].image}`} alt={filteredProjects[photoIndex].caption}/><div class="photo-controls"><button aria-label="Předchozí fotografie" onclick={()=>stepPhoto(-1)}><ChevronLeft/></button><p>{filteredProjects[photoIndex].caption}<span>{photoIndex+1} / {filteredProjects.length}</span></p><button aria-label="Další fotografie" onclick={()=>stepPhoto(1)}><ChevronRight/></button></div>{/if}</dialog>
